import { startOfDay, endOfDay } from 'date-fns';
import { utcToZonedTime } from 'date-fns-tz';
import { useCallback, useEffect, useMemo, useReducer } from 'react';
// This should be replaced with the Intl Locale weekInfo API (https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/Locale/weekInfo) as soon as it gets full support. It's currently not supported in Firefox, but there is an open issue for that - https://bugzilla.mozilla.org/show_bug.cgi?id=1693576
// TODO: remove as soon as Firefox gets support
import { useIntl } from 'react-intl';
import { getWeekStartByLocale } from 'weekstart';

import { getRegionalFormat } from '@dynatrace-sdk/user-preferences';

import { useCalendarNavigation } from './useCalendarNavigation.js';
import { _useId } from '../../../../core/hooks/useId.js';
import { TimeValue, TimeframeV2 } from '../../../../core/types/time.js';
import { useFormFieldMessagesContext } from '../../../forms-core/hooks/useFormFieldMessagesContext.js';
import type { FormFieldMessagesReducerAction } from '../../../forms-core/state/formfield-messages-state-reducer.js';
import {
  _isExpressionString,
  _parseTime,
} from '../../../forms-core/time/timeParser.js';
import {
  type _StringTimeOffset,
  _isTimeframeV2,
} from '../../../forms-core/time/types.js';
import type {
  _CalendarOnChangeType,
  _CalendarProps,
  _CalendarType,
  _CalendarValueType,
} from '../Calendar.js';
import { initialState as defaultState } from '../contexts/CalendarContext.js';
import { reducer } from '../state/calendar-state-reducer.js';
import { _validateCalendarSelection } from '../state/calendar-validation.js';
import type {
  _CalendarReducerAction,
  _CalendarState,
} from '../types/shared-types.js';
import { _convertToCalendarStructure } from '../utils/helpers.js';

//#region types
/** @internal */
export type UseCalendarProps<Type extends _CalendarType> =
  UseCalendarBaseProps &
    Pick<_CalendarProps<Type>, 'max' | 'min' | 'onChange' | 'type'> & {
      value: _CalendarOnChangeType<Type>;
    };

/** @internal */
export type UseCalendarBaseProps = {
  calendarRef: React.MutableRefObject<HTMLElement | null>;
  focusAfterViewChangeRef: React.MutableRefObject<HTMLButtonElement | null>;
};
//#endregion

/** @internal */
function _getTimeOffsetFromInitialValue<Type extends _CalendarType>(
  value?: _CalendarValueType<Type>,
  type: _CalendarType = 'single',
): _StringTimeOffset {
  if (_isTimeframeV2(value, type)) {
    if (!value) {
      return { from: 'startOfDay', to: 'endOfDay' };
    }

    return {
      from:
        value['from']?.type === 'iso8601' && value['from']?.absoluteDate
          ? value['from']?.absoluteDate
          : 'startOfDay',
      to:
        value['to']?.type === 'iso8601' && value['to']?.absoluteDate
          ? value['to']?.absoluteDate
          : 'endOfDay',
    };
  }

  if (typeof value === 'string') {
    return _isExpressionString(value) ? 'startOfDay' : value;
  }

  if (!value) {
    return 'startOfDay';
  }

  return value.toISOString();
}

/**
 * Checks whether the passed value is a Timeframe and checks if the value equals the second timeframe.
 * This check is for range calendars.
 */
function isDifferentTimeframe(
  calendarValue: Partial<TimeframeV2> | TimeValue | null,
  selectedDate: Partial<TimeframeV2> | TimeValue | null,
  type: _CalendarType,
) {
  return (
    _isTimeframeV2(calendarValue, type) &&
    !(
      calendarValue['from']?.value === selectedDate?.['from']?.value &&
      calendarValue['to']?.value === selectedDate?.['to']?.value
    )
  );
}

/**
 * Checks whether the passed value is of type TimeValue and checks if the value equals the second timeframe.
 * This check is for single calendars.
 */
function isDifferentTimeValue(
  calendarValue: Partial<TimeframeV2> | TimeValue | null,
  selectedDate: Partial<TimeframeV2> | TimeValue | null,
  type: _CalendarType,
) {
  return (
    !_isTimeframeV2(selectedDate, type) &&
    !_isTimeframeV2(calendarValue, type) &&
    calendarValue?.value !== selectedDate?.value
  );
}

/**
 * Calendar hook to initialize the calendar state and update it to prop changes.
 * @internal
 */
export function _useCalendar<Type extends _CalendarType>({
  calendarRef,
  focusAfterViewChangeRef,
  value,
  onChange,
  type = 'single',
  min,
  max,
}: UseCalendarProps<Type>) {
  const intl = useIntl();
  const uniqueId = _useId();

  const minDate = _parseTime(min);
  const maxDate = _parseTime(max);

  const timeOffset = useMemo(
    () => _getTimeOffsetFromInitialValue<Type>(value, type),
    // The timeOffset should only derrive from the value initially.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  const calendarValue = _convertToCalendarStructure<Type>(
    type,
    timeOffset,
    value,
  );

  const activeISODate = _isTimeframeV2(calendarValue, type)
    ? calendarValue.from?.absoluteDate
    : calendarValue?.absoluteDate;

  const initialState = {
    ...defaultState,
    position: type === 'single' ? undefined : 'from',
    type,
    min: minDate ? startOfDay(new Date(minDate.absoluteDate)) : undefined,
    max: maxDate ? endOfDay(new Date(maxDate.absoluteDate)) : undefined,
    selectedDate: calendarValue,
    activeDate: activeISODate ? new Date(activeISODate) : undefined,
    // If it is initialized with a timeoffset it keeps the offset.
    // This will be customizable in the future.
    timeOffset,
  };

  const { dispatch: formMessageDispatch } = useFormFieldMessagesContext();

  const callback = useCallback(
    (state: _CalendarState, action: _CalendarReducerAction) =>
      reducer(
        state,
        action,
        (args: FormFieldMessagesReducerAction) => {
          // Delay the ErrorMessage update by a tick to not update the calendar state and the message state at the same time.
          window.setTimeout(() => {
            formMessageDispatch(args);
          });
        },
        onChange,
      ),
    [formMessageDispatch, onChange],
  );

  const [state, dispatch] = useReducer(
    callback,
    // activeDate might be undefined but will be set in the initializer, to ensure the correct timezone.
    initialState as _CalendarState,
    (state) => {
      // Make sure the state initializes with a new Date when the component is created
      // instead of on the module scope.
      // Extract the user-settings timezone to use for the calculation
      const configuredTimezone =
        intl.timeZone ?? Intl.DateTimeFormat().resolvedOptions().timeZone;

      // Get a UTC Time of now, then run a startOfDay for the UTC time and
      // convert the given time back to the user time zone.
      const today = startOfDay(
        utcToZonedTime(Date.now(), configuredTimezone.replace(/UTC/, '')),
      );

      const internalError = _validateCalendarSelection(
        state.selectedDate,
        state,
        (args: FormFieldMessagesReducerAction) => {
          // Delay the ErrorMessage update by a tick to not update the calendar state and the message state at the same time.
          window.setTimeout(() => {
            formMessageDispatch(args);
          });
        },
      );

      return {
        ...state,
        errorId: internalError,
        activeDate: state.activeDate ?? today,
        today,
      };
    },
  );
  // Get localized first day of the week to correctly display the weekday labels
  const region = useMemo(() => getRegionalFormat(), []);

  /** Updates the state in case of a controlled update from the outside. */
  if (
    isDifferentTimeframe(calendarValue, state.selectedDate, type) ||
    isDifferentTimeValue(calendarValue, state.selectedDate, type)
  ) {
    dispatch({
      type: 'valueChanged',
      payload: calendarValue,
    });
  }

  if (type !== state.type) {
    dispatch({
      type: 'typeChanged',
      payload: { type, position: type === 'single' ? undefined : 'from' },
    });
  }

  // The calendar's state needs to be updated when the localization information changes
  useEffect(() => {
    // TODO: remove this dependency as soon as Firefox supports the new Intl.Locale weekInfo API (and use it instead)
    const weekStartsOn = getWeekStartByLocale(region);
    dispatch({
      type: 'weekStartsOnChange',
      payload: weekStartsOn,
    });
  }, [dispatch, region]);

  useCalendarNavigation({
    calendarRef,
    focusAfterViewChangeRef,
    state,
    dispatch,
  });

  return { state, dispatch, uniqueId };
}
